import type { ReactNode } from 'react';
import { Pressable, View } from 'react-native';
import * as Haptics from 'expo-haptics';

import { radius, spacing } from '../theme/tokens';
import { useTheme } from '../theme/useTheme';
import { Text } from './Text';

export type ChipProps = {
  label: string;
  onPress?: () => void;
  selected?: boolean;
  icon?: ReactNode;
  testID?: string;
};

export function Chip({ label, onPress, selected = false, icon, testID }: ChipProps) {
  const theme = useTheme();
  const body = (
    <View
      style={{
        flexDirection: 'row',
        alignItems: 'center',
        gap: spacing.xs,
        paddingVertical: spacing.md,
        paddingHorizontal: spacing.lg,
        borderRadius: radius.full,
        backgroundColor: selected ? theme.color.accent : theme.color.surface2,
        minHeight: 44,
      }}
    >
      {icon != null ? icon : null}
      <Text variant="label" tone={selected ? 'onAccent' : 'secondary'}>
        {label}
      </Text>
    </View>
  );

  if (onPress) {
    return (
      <Pressable
        testID={testID}
        onPress={() => {
          void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
          onPress();
        }}
        accessibilityRole="button"
        accessibilityLabel={label}
        accessibilityState={{ selected }}
        hitSlop={8}
        style={({ pressed }) => (pressed ? { opacity: 0.7 } : null)}
      >
        {body}
      </Pressable>
    );
  }
  return <View testID={testID}>{body}</View>;
}
